@CrossOrigin
@RestController
@RequestMapping("/AttestationQuery")
public class AttestationQueryRestController extends BaseSpringRestController {
	
	public AttestationQueryRestController( AttestationService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Attestation using a UUID
     * @param		UUID attestationId
     * @return		Attestation
     */    
    @GetMapping("/load")
    public Attestation load( @RequestParam(required=true) UUID attestationId ) {
    	Attestation entity = null;

    	try {  
    		entity = service.getAttestation( new AttestationFetchOneSummary( attestationId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Attestation using Id " + attestationId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Attestation business objects
     * @return		Set<Attestation>
     */
    @GetMapping("/")
    public List<Attestation> loadAll() {                
    	List<Attestation> attestationList = null;
        
    	try {
            // load the Attestation
            attestationList = service.getAllAttestation();
            
            if ( attestationList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Attestations" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Attestations ", exc );
        	return null;
        }

        return attestationList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Attestation attestation = null;
    protected AttestationService service = null;
    private static final Logger LOGGER = Logger.getLogger(AttestationQueryRestController.class.getName());
    
}
